        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

sales_by_model_with_m5_vin = Dealership.Cars.WHERE(
    LIKE(LOWER(vin_number), '%m5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    number_of_sales=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        )
    ),
    total_revenue=SUM(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (LOWER(car.make) == LOWER("Toyota"))
        ).sale_price
    )
)

result = Sales.WHERE(
    (YEAR(sale_date) == 2023) & 
    (ISIN(MONTH(sale_date), (1, 2, 3)))
).CALCULATE(
    asp_q1_2023 = AVG(Sales.sale_price)
)

result = Dealership.CALCULATE(
