).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Dealership.CALCULATE(
    total_sales_count=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME('now')) >= 0) & 
            (DATEDIFF("days", sale_date, DATETIME('now')) <= 7)
        )
    )
)

result = Customers.WHERE(
