).ORDER_BY(
    num_treatments.DESC(),
    drug_name.ASC()
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            CONTAINS(LOWER(diagnosis.diag_name), 'psoriasis') &
            (drug.fda_appr_dt != None) &
            (DATEDIFF("days", end_dt, DATETIME('now')) <= 180)
