            LIKE(LOWER(diagnosis.diag_name), '%psoriasis%') &
            PRESENT(drug.fda_appr_dt) &
            (end_dt >= DATETIME('now', '-6 months'))
        )
    )
)

result = Treatments.WHERE(
    HAS(adverse_events) == 1
).adverse_events.WHERE(
    DATEDIFF("days", treatment.start_dt, reported_dt) <= 10
).CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_date=treatment.start_dt,
    adverse_event_date=reported_dt,
    adverse_event_description=description
)

result = Treatments.WHERE(
    is_placebo == True
).WHERE(
    HAS(concomitant_meds.WHERE(
        DATEDIFF("days", treatment.start_dt, start_dt) <= 14
    )) == 1
).CALCULATE(
    treatment_id,
    treatment_start_dt=start_dt,
    treatment_end_dt=end_dt,
    concomitant_med_start_dates=concomitant_meds.CALCULATE(
        start_date=start_dt
    ).start_date,
    concomitant_med_end_dates=concomitant_meds.CALCULATE(
        end_date=end_dt
    ).end_date
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

# First, create a collection of male patients with private insurance and calculate their current age in years.
male_private_patients_with_age = DermTreatment.Patients.WHERE(
    (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
).CALCULATE(
    age=DATEDIFF("years", date_of_birth, 'now')
)

# Next, calculate the average of the ages from the collection above and round it to the nearest integer.
result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(male_private_patients_with_age.age), 0)
)

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()

lub_per_user = Users.CALCULATE(
