        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    )
).ORDER_BY(total_duration.DESC())

result = Ewallet.CALCULATE(
    total_count=COUNT(UserSessions.WHERE(
        DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
    ))
)

result = Transactions.WHERE(
