    merchant_id=receiver_id
)

result = Users.WHERE(
    HAS(notifications.WHERE(CONTAINS(LOWER(notification_type), "transaction"))) == 1
).CALCULATE(
    user_id=uid
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(
